int main(void){Combat g;combat_init(&g,1500,1500,NULL,NULL);assert(g.walkPercent==84&&g.attackSoundDelayMs==0);DeveloperUI d={.tab=0,.row=7};for(int i=0;i<100;i++)dev_input(&d,&g,8192);assert(g.attackSoundDelayMs==300);for(int i=0;i<100;i++)dev_input(&d,&g,4096);assert(g.attackSoundDelayMs==0);dev_input(&d,&g,2);assert(g.attackSoundDelayMs==0);d.row=6;g.walkPercent=100;dev_input(&d,&g,2);assert(g.walkPercent==84);
 for(unsigned mask=0;mask<128;mask++){g.popupDisabled=mask;for(unsigned bit=1;bit<=POP_SYSTEM;bit*=2){combat_notice(&g,bit,"Notice");assert(combat_popup_visible(&g)==!(mask&bit));}combat_number(&g,g.x,g.y,20,1,0);assert(g.damageNext==mask+1);SavedCharacter a,b;unsigned char raw[SAVE_BYTES];save_capture(&a,&g,1);assert(save_valid(&a));save_encode(raw,&a);assert(save_decode(&b,raw)==1&&b.popupDisabled==mask);a.popupDisabled=128;assert(!save_valid(&a));}g.popupDisabled=POP_DAMAGE;
 for(int a=0;a<4;a++)for(int b=0;b<4;b++)for(int c=0;c<4;c++)for(int e=0;e<4;e++){if(a==b||a==c||a==e||b==c||b==e||c==e)continue;WindowUI u={0};int order[]={a,b,c,e};for(int i=0;i<4;i++)ui_open(&u,order[i],1);for(int i=3;i>=0;i--){assert(u.focus==4+order[i]);ui_close(&u,order[i]);assert(u.active==(i>0));}ui_open(&u,a,1);ui_open(&u,b,1);ui_open(&u,a,1);ui_close(&u,a);assert(u.active&&u.focus==4+b);}
 assert(dev_spawn(&g,0,0));CombatMob*m=&g.mobs[MOB_COUNT-1];assert(m->training&&!m->trainingActive);g.debugFreeze=1;float ox=m->x,oy=m->y;for(int i=0;i<20;i++)combat_tick(&g,.05f,0,0);assert(m->x==ox&&m->y==oy);d.tab=1;d.row=8;dev_input(&d,&g,2);assert(m->trainingActive);float initial=combat_dist(g.x,g.y,m->x,m->y);for(int i=0;i<30;i++)combat_tick(&g,.05f,0,0);assert(combat_dist(g.x,g.y,m->x,m->y)<initial);dev_input(&d,&g,2);ox=m->x;oy=m->y;for(int i=0;i<20;i++)combat_tick(&g,.05f,0,0);assert(m->x==ox&&m->y==oy);m->trainingActive=1;m->hp=0;m->deadAt=-100;for(int i=0;i<500;i++)combat_tick(&g,.05f,0,0);assert(m->hp==0);
 for(int ticks=1;ticks<=1000;ticks++){float total=ticks*.01f;int last=-1,count=0,spacing=-1;for(int p=0;p<46;p++)if(cast_quarter_gap(total,p)){if(last>=0){if(spacing<0)spacing=p-last;assert(p-last==spacing);assert(p-last>1);}last=p;count++;}int n=(int)ceilf(fminf(12,total*2));assert(count==n-1);}
 TargetTrack41 tr={0};TargetBounds41 out;unsigned small[5]={40,50,20,20,0},large[5]={20,20,70,80,0};assert(target_bounds41(&tr,1,1,small,64,90,320,240,1,.016f,&out));float w=out.x1-out.x0;assert(target_bounds41(&tr,1,1,large,64,90,320,240,1,.016f,&out));assert(out.x0<=273&&out.x1>=349&&out.y0<=167&&out.y1>=253);assert(target_bounds41(&tr,1,1,small,64,90,320,240,1,.016f,&out));assert(out.x1-out.x0>w);for(int i=0;i<100;i++)target_bounds41(&tr,1,1,small,64,90,320,240,1,.016f,&out);assert(fabsf(out.x1-out.x0-w)<.001f);target_bounds41(&tr,2,1,large,64,90,320,240,1,.016f,&out);target_bounds41(&tr,2,2,small,64,90,320,240,1,.016f,&out);assert(fabsf(out.x1-out.x0-w)<.001f);
 for(int i=0;i<60;i++){float r=spell_circle_radius41(i*.01f);assert(r>=10&&r<=28);if(i)assert(r<spell_circle_radius41((i-1)*.01f));}for(int i=0;i<5;i++){float x,y;spell_storm_point41(i,0,&x,&y);assert(hypotf(x,y)<=16.001f);}puts("PASS41 MRU close permutations/reopen, slider bounds/default84%, active/idle/no-respawn practice, uniform half-second gaps, padded expanding/relaxing target bounds, shrinking circle and bounded storm spread");}
